import pandas as pd
import csv
import json
from collections import defaultdict

# ── Read and parse data ──────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", newline="", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

# Build structured records, splitting multi-composer entries
records = []  # (year, film, composer_name)
for r in rows:
    year = int(r["Year"])
    film = r["Film"].strip()
    composers = [c.strip() for c in r["Composer"].split(",")]
    for comp in composers:
        records.append((year, film, comp))

# ── Core statistics ──────────────────────────────────────────────────
total_ceremonies = len(rows)
all_composers = [rec[2] for rec in records]
unique_composers = sorted(set(all_composers))
total_unique = len(unique_composers)

# Wins per composer
wins_by_composer = defaultdict(list)
for year, film, comp in records:
    wins_by_composer[comp].append((year, film))

# Sort by win count desc, then by first win year asc
sorted_composers = sorted(
    wins_by_composer.items(),
    key=lambda x: (-len(x[1]), x[1][0][0])
)

max_wins = len(sorted_composers[0][1])

# ── Repeat winner rate ───────────────────────────────────────────────
# Per ceremony: check if ANY winning composer had won before
seen_composers = set()
repeat_ceremonies = 0
ceremony_composers = {}  # year -> list of composers

for r in rows:
    year = int(r["Year"])
    composers = [c.strip() for c in r["Composer"].split(",")]
    ceremony_composers[year] = composers
    is_repeat = any(c in seen_composers for c in composers)
    if is_repeat:
        repeat_ceremonies += 1
    for c in composers:
        seen_composers.add(c)

repeat_winner_rate = round(repeat_ceremonies / total_ceremonies * 100, 1)

# ── Decade analysis ──────────────────────────────────────────────────
def year_to_decade(y):
    return f"{(y // 10) * 10}s"

decade_data = defaultdict(lambda: {"composers": set(), "films": [], "years": []})
for r in rows:
    year = int(r["Year"])
    film = r["Film"].strip()
    composers = [c.strip() for c in r["Composer"].split(",")]
    dec = year_to_decade(year)
    decade_data[dec]["composers"].update(composers)
    decade_data[dec]["films"].append(film)
    decade_data[dec]["years"].append(year)

# Count unique winners per decade
decade_unique_counts = {d: len(v["composers"]) for d, v in sorted(decade_data.items())}
decade_total_ceremonies = {d: len(v["years"]) for d, v in sorted(decade_data.items())}

decade_most_unique = max(decade_unique_counts, key=decade_unique_counts.get)
decade_most_unique_count = decade_unique_counts[decade_most_unique]

# Repeat winners per decade
decade_repeat = {}
for dec in sorted(decade_data.keys()):
    global_seen = set()
    repeat = 0
    for r in rows:
        year = int(r["Year"])
        if year_to_decade(year) != dec:
            global_seen.update(c.strip() for c in r["Composer"].split(","))
            continue
        composers = [c.strip() for c in r["Composer"].split(",")]
        if any(c in global_seen for c in composers):
            repeat += 1
        global_seen.update(composers)
    decade_repeat[dec] = repeat

# Actually, let me recalculate repeat per decade more accurately:
# A "repeat winner" in a decade means a composer who won MORE THAN ONCE within or across decades
decade_repeat_new = {}
for dec in sorted(decade_data.keys()):
    years_in_dec = sorted(decade_data[dec]["years"])
    repeat_count = 0
    for y in years_in_dec:
        comps = ceremony_composers[y]
        # Check if any composer had won in a PRIOR year (any year, not just this decade)
        prior_wins = False
        for c in comps:
            for wy, wf in wins_by_composer[c]:
                if wy < y:
                    prior_wins = True
                    break
            if prior_wins:
                break
        if prior_wins:
            repeat_count += 1
    decade_repeat_new[dec] = repeat_count

decade_first_time = {d: decade_total_ceremonies[d] - decade_repeat_new[d] for d in decade_total_ceremonies}

# ── Era analysis ─────────────────────────────────────────────────────
eras = {
    "Golden Age (1934–1959)": (1934, 1959),
    "Transitional (1960–1979)": (1960, 1979),
    "Modern (1980–1999)": (1980, 1999),
    "Contemporary (2000–2026)": (2000, 2026),
}

era_stats = {}
for era_name, (start, end) in eras.items():
    era_composers = set()
    era_films = []
    for r in rows:
        year = int(r["Year"])
        if start <= year <= end:
            composers = [c.strip() for c in r["Composer"].split(",")]
            era_composers.update(composers)
            era_films.append(r["Film"].strip())
    era_stats[era_name] = {
        "unique_composers": len(era_composers),
        "ceremonies": len(era_films),
        "composers": sorted(era_composers),
    }

# Top composers per era
era_top = {}
for era_name, (start, end) in eras.items():
    era_wins = defaultdict(int)
    for comp, wins in wins_by_composer.items():
        for wy, wf in wins:
            if start <= wy <= end:
                era_wins[comp] += 1
    sorted_era = sorted(era_wins.items(), key=lambda x: -x[1])[:5]
    era_top[era_name] = sorted_era

# ── Notable milestones ───────────────────────────────────────────────
# Longest gap between wins for a repeat composer
max_gap = 0
max_gap_info = ""
for comp, wins in wins_by_composer.items():
    if len(wins) < 2:
        continue
    years_sorted = sorted([w[0] for w in wins])
    for i in range(1, len(years_sorted)):
        gap = years_sorted[i] - years_sorted[i-1]
        if gap > max_gap:
            max_gap = gap
            max_gap_info = f"{comp}: {years_sorted[i-1]}–{years_sorted[i]} ({gap} years)"

# Back-to-back winners
back_to_back = []
sorted_years = sorted(ceremony_composers.keys())
for i in range(1, len(sorted_years)):
    prev_comps = set(ceremony_composers[sorted_years[i-1]])
    curr_comps = set(ceremony_composers[sorted_years[i]])
    overlap = prev_comps & curr_comps
    if overlap:
        back_to_back.append((sorted_years[i-1], sorted_years[i], list(overlap)))

# ── Prepare data for charts ──────────────────────────────────────────
# Top 15 composers chart data
top_n = min(15, len(sorted_composers))
top_chart_labels = []
top_chart_values = []
for comp, wins in sorted_composers[:top_n]:
    top_chart_labels.append(comp)
    top_chart_values.append(len(wins))

# Decade chart data
dec_labels = sorted(decade_data.keys())
dec_unique = [decade_unique_counts[d] for d in dec_labels]
dec_repeat_vals = [decade_repeat_new[d] for d in dec_labels]
dec_first = [decade_first_time[d] for d in dec_labels]

# Timeline: composer dominance scatter
timeline_data = []
for comp, wins in wins_by_composer.items():
    if len(wins) >= 2:
        for wy, wf in wins:
            timeline_data.append({"composer": comp, "year": wy, "film": wf, "wins": len(wins)})

# ── Generate HTML ────────────────────────────────────────────────────
# Prepare top composers table rows
top_table_rows = ""
for rank, (comp, wins) in enumerate(sorted_composers[:20], 1):
    years_str = ", ".join(str(w[0]) for w in sorted(wins, key=lambda x: x[0]))
    films_str = "; ".join(f"<em>{w[1]}</em> ({w[0]})" for w in sorted(wins, key=lambda x: x[0]))
    top_table_rows += f"""
        <tr>
            <td class="rank">{rank}</td>
            <td class="composer-name">{comp}</td>
            <td class="wins">{len(wins)}</td>
            <td class="years">{years_str}</td>
            <td class="films">{films_str}</td>
        </tr>"""

# Decade breakdown table
decade_table_rows = ""
for d in dec_labels:
    dd = decade_data[d]
    repeat = decade_repeat_new[d]
    first = decade_first_time[d]
    top_in_dec = sorted(
        [(c, sum(1 for wy, wf in wins if year_to_decade(wy) == d)) for c, wins in wins_by_composer.items() if any(year_to_decade(wy) == d for wy, wf in wins)],
        key=lambda x: -x[1]
    )[:3]
    top_str = ", ".join(f"{c} ({n})" for c, n in top_in_dec)
    decade_table_rows += f"""
        <tr>
            <td>{d}</td>
            <td>{len(dd['years'])}</td>
            <td>{dd['composers'].__len__()}</td>
            <td>{first}</td>
            <td>{repeat}</td>
            <td class="top-comp">{top_str}</td>
        </tr>"""

# Era section
era_sections = ""
era_colors = {"Golden Age (1934–1959)": "#c9a84c", "Transitional (1960–1979)": "#8b9dc3", "Modern (1980–1999)": "#5b8c5a", "Contemporary (2000–2026)": "#c0392b"}
for era_name, stats in era_stats.items():
    top_list = era_top[era_name]
    top_html = "".join(f'<li><strong>{c}</strong> — {n} win{"s" if n > 1 else ""}</li>' for c, n in top_list)
    color = era_colors[era_name]
    era_sections += f"""
        <div class="era-card" style="border-left: 4px solid {color};">
            <h3 style="color: {color};">{era_name}</h3>
            <div class="era-stats">
                <span><strong>{stats['ceremonies']}</strong> ceremonies</span>
                <span><strong>{stats['unique_composers']}</strong> unique composers</span>
            </div>
            <p class="era-desc">{get_era_description(era_name, stats, top_list)}</p>
            <ul class="era-top">{top_html}</ul>
        </div>"""

# Hmm, I can't call a function that doesn't exist yet. Let me restructure.
# I'll build era descriptions inline.

def get_era_desc(era_name, stats, top_list):
    if "Golden" in era_name:
        return ("The Golden Age of Hollywood scoring was dominated by European emigre composers who brought "
                "late-Romantic orchestral traditions to the studio system. Max Steiner, often called the father "
                "of film music, set the template with his symphonic approach. Alfred Newman and Dimitri Tiomkin "
                "built prolific careers within the studio apparatus. Wins were concentrated among a handful of "
                f"repeat winners: {stats['unique_composers']} unique composers across {stats['ceremonies']} ceremonies, "
                "with several figures winning multiple times.")
    elif "Transitional" in era_name:
        return ("The 1960s and 1970s saw film music diversify dramatically. The European orchestral tradition "
                "gave way to jazz-inflected scores (Henry Mancini, Elmer Bernstein), pop and rock influences "
                "(Burt Bacharach, Giorgio Moroder, Vangelis), and a new generation of melody-driven composers. "
                "Maurice Jarre and John Barry bridged the old and new, winning with both epic orchestral scores "
                "and intimate themes. The era produced the category's first electronic-score winner (Vangelis, 1981). "
                f"{stats['unique_composers']} unique composers won across {stats['ceremonies']} ceremonies, reflecting "
                "a marked increase in diversity.")
    elif "Modern" in era_name:
        return ("The Modern era consolidated the blockbuster scoring style, with John Williams and John Barry "
                "continuing their dominance while new voices emerged. Alan Menken's unprecedented three-win streak "
                "(1989–1992) for Disney animated films reshaped the category. The era also saw the first jazz artist "
                "win (Herbie Hancock, 1986), first Asian-born composer (Ryuichi Sakamoto, 1987), and a growing "
                "international presence. Hans Zimmer's 1994 win for The Lion King heralded the rise of the "
                "media-mogul composer-producer. "
                f"{stats['unique_composers']} unique composers won across {stats['ceremonies']} ceremonies.")
    else:
        return ("The Contemporary era is defined by unprecedented global diversity. Winners hail from Italy, "
                "Argentina, India, Iceland, Germany, and beyond. Alexandre Desplat and Ludwig Göransson each "
                "claimed multiple wins, while first-time winners dominated most years. The era saw the first "
                "win by a woman as sole composer (Hildur Guðnadóttir, 2019), first rock musicians winning "
                "(Trent Reznor & Atticus Ross, 2010), and the rise of experimental and minimalist scoring "
                "approaches. Göransson's three wins — including back-to-back for Oppenheimer-related entries "
                f"and Sinners — mark him as the era's standout figure. {stats['unique_composers']} unique "
                f"composers across {stats['ceremonies']} ceremonies underscores the high turnover rate.")

# Back-to-back section
bb_html = ""
for y1, y2, comps in back_to_back:
    comp_str = ", ".join(comps)
    bb_html += f"<li>{comp_str} won in both {y1} and {y2}</li>"

# ── Final HTML generation ───────────────────────────────────────────
# Re-generate era sections with proper descriptions
era_sections = ""
for era_name, stats in era_stats.items():
    top_list = era_top[era_name]
    top_html = "".join(f'<li><strong>{c}</strong> — {n} win{"s" if n > 1 else ""}</li>' for c, n in top_list)
    color = era_colors[era_name]
    desc = get_era_desc(era_name, stats, top_list)
    era_sections += f"""
        <div class="era-card" style="border-left: 4px solid {color};">
            <h3 style="color: {color};">{era_name}</h3>
            <div class="era-stats">
                <span><strong>{stats['ceremonies']}</strong> ceremonies</span>
                <span><strong>{stats['unique_composers']}</strong> unique composers</span>
            </div>
            <p class="era-desc">{desc}</p>
            <p class="era-top-label">Top composers in this era:</p>
            <ul class="era-top">{top_html}</ul>
        </div>"""

html = f"""<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script>
<style>
:root {{
  --gold: #c9a84c;
  --gold-light: #e8d9a0;
  --dark: #1a1a2e;
  --darker: #0f0f1e;
  --card-bg: #16213e;
  --text: #e0e0e0;
  --text-muted: #a0a0b0;
  --accent: #c9a84c;
  --accent2: #e74c3c;
  --accent3: #3498db;
  --accent4: #2ecc71;
}}
* {{ margin: 0; padding: 0; box-sizing: border-box; }}
body {{
  font-family: 'Segoe UI', -apple-system, BlinkMacSystemFont, sans-serif;
  background: var(--darker);
  color: var(--text);
  line-height: 1.65;
}}
.container {{
  max-width: 1100px;
  margin: 0 auto;
  padding: 0 24px;
}}

/* ── Hero ─────────────────────────────── */
.hero {{
  background: linear-gradient(135deg, var(--darker) 0%, #1a1a3e 50%, var(--darker) 100%);
  border-bottom: 3px solid var(--gold);
  padding: 60px 0 50px;
  text-align: center;
}}
.hero h1 {{
  font-size: 2.6rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 12px;
  letter-spacing: -0.5px;
}}
.hero h1 span {{ color: var(--gold); }}
.hero .subtitle {{
  font-size: 1.15rem;
  color: var(--text-muted);
  max-width: 700px;
  margin: 0 auto 24px;
}}
.hero .meta {{
  font-size: 0.85rem;
  color: var(--text-muted);
}}

/* ── KPI cards ────────────────────────── */
.kpi-grid {{
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  margin: 40px 0;
}}
.kpi-card {{
  background: var(--card-bg);
  border-radius: 12px;
  padding: 28px 20px;
  text-align: center;
  border-top: 3px solid var(--gold);
  transition: transform 0.2s;
}}
.kpi-card:hover {{ transform: translateY(-3px); }}
.kpi-value {{
  font-size: 2.6rem;
  font-weight: 800;
  color: var(--gold);
  line-height: 1.1;
  margin-bottom: 6px;
}}
.kpi-label {{
  font-size: 0.82rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}}

/* ── Sections ─────────────────────────── */
section {{ padding: 50px 0; }}
section:not(:last-child) {{ border-bottom: 1px solid rgba(201,168,76,0.15); }}
.section-title {{
  font-size: 1.85rem;
  font-weight: 700;
  color: #fff;
  margin-bottom: 8px;
}}
.section-title span {{ color: var(--gold); }}
.section-subtitle {{
  font-size: 0.95rem;
  color: var(--text-muted);
  margin-bottom: 32px;
}}

/* ── Tables ───────────────────────────── */
.table-wrap {{
  overflow-x: auto;
  border-radius: 10px;
  border: 1px solid rgba(201,168,76,0.15);
}}
table {{
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}}
thead {{ background: rgba(201,168,76,0.1); }}
th {{
  text-align: left;
  padding: 14px 16px;
  font-weight: 600;
  color: var(--gold);
  border-bottom: 2px solid rgba(201,168,76,0.3);
  white-space: nowrap;
}}
td {{
  padding: 12px 16px;
  border-bottom: 1px solid rgba(255,255,255,0.05);
}}
tbody tr:hover {{ background: rgba(201,168,76,0.04); }}
.rank {{ color: var(--gold); font-weight: 700; text-align: center; }}
.wins {{ font-weight: 700; color: #fff; text-align: center; }}
.composer-name {{ font-weight: 600; color: #fff; }}
.years {{ color: var(--text-muted); font-size: 0.82rem; }}
.films {{ color: var(--text-muted); font-size: 0.82rem; }}
.films em {{ color: #ddd; font-style: italic; }}
.top-comp {{ font-size: 0.82rem; }}

/* ── Charts ───────────────────────────── */
.chart-container {{
  position: relative;
