import csv
import json
from collections import defaultdict

# ── Read and parse data ──────────────────────────────────────────────
rows = []
with open("/app/benchmark/data.csv", newline="", encoding="utf-8") as f:
    reader = csv.DictReader(f)
    for r in reader:
        rows.append(r)

# Build structured records, splitting multi-composer entries
records = []
for r in rows:
    year = int(r["Year"])
    film = r["Film"].strip()
    composers = [c.strip() for c in r["Composer"].split(",")]
    for comp in composers:
        records.append((year, film, comp))

# ── Core statistics ──────────────────────────────────────────────────
total_ceremonies = len(rows)
all_composers = [rec[2] for rec in records]
unique_composers = sorted(set(all_composers))
total_unique = len(unique_composers)

wins_by_composer = defaultdict(list)
for year, film, comp in records:
    wins_by_composer[comp].append((year, film))

sorted_composers = sorted(
    wins_by_composer.items(),
    key=lambda x: (-len(x[1]), x[1][0][0])
)

max_wins = len(sorted_composers[1][1])  # Check top two

# Verify max_wins: top two composers should both have 4
print("Top composers by wins:")
for comp, wins in sorted_composers[:5]:
    print(f"  {comp}: {len(wins)} wins — {sorted([w[0] for w in wins])}")

max_wins = len(sorted_composers[0][1])

# ── Repeat winner rate ───────────────────────────────────────────────
seen_composers = set()
repeat_ceremonies = 0
ceremony_composers = {}

for r in rows:
    year = int(r["Year"])
    composers = [c.strip() for c in r["Composer"].split(",")]
    ceremony_composers[year] = composers
    is_repeat = any(c in seen_composers for c in composers)
    if is_repeat:
        repeat_ceremonies += 1
    for c in composers:
        seen_composers.add(c)

repeat_winner_rate = round(repeat_ceremonies / total_ceremonies * 100, 1)

# ── Decade analysis ──────────────────────────────────────────────────
def year_to_decade(y):
    return f"{(y // 10) * 10}s"

decade_data = defaultdict(lambda: {"composers": set(), "films": [], "years": []})
for r in rows:
    year = int(r["Year"])
    film = r["Film"].strip()
    composers = [c.strip() for c in r["Composer"].split(",")]
    dec = year_to_decade(year)
    decade_data[dec]["composers"].update(composers)
    decade_data[dec]["films"].append(film)
    decade_data[dec]["years"].append(year)

decade_unique_counts = {d: len(v["composers"]) for d, v in sorted(decade_data.items())}
decade_total_ceremonies = {d: len(v["years"]) for d, v in sorted(decade_data.items())}

decade_most_unique = max(decade_unique_counts, key=decade_unique_counts.get)
decade_most_unique_count = decade_unique_counts[decade_most_unique]

# Repeat vs first-time per decade
decade_repeat_new = {}
for dec in sorted(decade_data.keys()):
    years_in_dec = sorted(decade_data[dec]["years"])
    repeat_count = 0
    for y in years_in_dec:
        comps = ceremony_composers[y]
        prior_wins = False
        for c in comps:
            for wy, wf in wins_by_composer[c]:
                if wy < y:
                    prior_wins = True
                    break
            if prior_wins:
                break
        if prior_wins:
            repeat_count += 1
    decade_repeat_new[dec] = repeat_count

decade_first_time = {d: decade_total_ceremonies[d] - decade_repeat_new[d] for d in decade_total_ceremonies}

# ── Era analysis ─────────────────────────────────────────────────────
eras = {
    "Golden Age (1934–1959)": (1934, 1959),
    "Transitional (1960–1979)": (1960, 1979),
    "Modern (1980–1999)": (1980, 1999),
    "Contemporary (2000–2026)": (2000, 2026),
}

era_stats = {}
for era_name, (start, end) in eras.items():
    era_composers = set()
    era_films = []
    for r in rows:
        year = int(r["Year"])
        if start <= year <= end:
            composers = [c.strip() for c in r["Composer"].split(",")]
            era_composers.update(composers)
            era_films.append(r["Film"].strip())
    era_stats[era_name] = {
        "unique_composers": len(era_composers),
        "ceremonies": len(era_films),
        "composers": sorted(era_composers),
    }

# Top composers per era
era_top = {}
for era_name, (start, end) in eras.items():
    era_wins = defaultdict(int)
    for comp, wins in wins_by_composer.items():
        for wy, wf in wins:
            if start <= wy <= end:
                era_wins[comp] += 1
    sorted_era = sorted(era_wins.items(), key=lambda x: -x[1])[:5]
    era_top[era_name] = sorted_era

# ── Notable milestones ───────────────────────────────────────────────
max_gap = 0
max_gap_info = ""
for comp, wins in wins_by_composer.items():
    if len(wins) < 2:
        continue
    years_sorted = sorted([w[0] for w in wins])
    for i in range(1, len(years_sorted)):
        gap = years_sorted[i] - years_sorted[i-1]
        if gap > max_gap:
            max_gap = gap
            max_gap_info = f"{comp}: {years_sorted[i-1]} to {years_sorted[i]} ({gap} years)"

# Back-to-back winners (same composer winning consecutive ceremonies)
back_to_back = []
sorted_years = sorted(ceremony_composers.keys())
for i in range(1, len(sorted_years)):
    prev_comps = set(ceremony_composers[sorted_years[i-1]])
    curr_comps = set(ceremony_composers[sorted_years[i]])
    overlap = prev_comps & curr_comps
    if overlap:
        back_to_back.append((sorted_years[i-1], sorted_years[i], list(overlap)))

# ── Chart data ───────────────────────────────────────────────────────
top_n = min(15, len(sorted_composers))
top_chart_labels = []
top_chart_values = []
for comp, wins in sorted_composers[:top_n]:
    top_chart_labels.append(comp)
    top_chart_values.append(len(wins))

dec_labels = sorted(decade_data.keys())
dec_unique = [decade_unique_counts[d] for d in dec_labels]
dec_repeat_vals = [decade_repeat_new[d] for d in dec_labels]
dec_first = [decade_first_time[d] for d in dec_labels]

timeline_data = []
for comp, wins in wins_by_composer.items():
    if len(wins) >= 2:
        for wy, wf in wins:
            timeline_data.append({"composer": comp, "year": wy, "film": wf, "wins": len(wins)})

# ── Build HTML components ────────────────────────────────────────────

# Top composers table rows
top_table_rows = ""
for rank, (comp, wins) in enumerate(sorted_composers[:20], 1):
    years_str = ", ".join(str(w[0]) for w in sorted(wins, key=lambda x: x[0]))
    films_str = "; ".join(
        f"<em>{w[1]}</em> ({w[0]})" for w in sorted(wins, key=lambda x: x[0])
    )
    top_table_rows += f"""
        <tr>
            <td class="rank">{rank}</td>
            <td class="composer-name">{comp}</td>
            <td class="wins">{len(wins)}</td>
            <td class="years">{years_str}</td>
            <td class="films">{films_str}</td>
        </tr>"""

# Decade breakdown table
decade_table_rows = ""
for d in dec_labels:
    dd = decade_data[d]
    repeat = decade_repeat_new[d]
    first = decade_first_time[d]
    top_in_dec = sorted(
        [(c, sum(1 for wy, wf in wins_by_composer[c] if year_to_decade(wy) == d))
         for c in dd["composers"]],
        key=lambda x: -x[1]
    )[:3]
    top_str = ", ".join(f"{c} ({n})" for c, n in top_in_dec)
    decade_table_rows += f"""
        <tr>
            <td>{d}</td>
            <td>{len(dd['years'])}</td>
            <td>{len(dd['composers'])}</td>
            <td>{first}</td>
            <td>{repeat}</td>
