# Era descriptions
def get_era_desc(era_name, stats, top_list):
    if "Golden" in era_name:
        return (
            "The Golden Age of Hollywood scoring was dominated by European emigre composers "
            "who brought late-Romantic orchestral traditions to the studio system. Max Steiner, "
